function sensitiveOperation(user, amount) {
  console.log(`User ${user} transferred ${amount}`);
}

const validator = {
  apply(target, thisArg, args) {
    const [user, amount] = args;
    if (typeof amount !== 'number' || amount <= 0) {
      throw new Error('Invalid amount');
    }
    return Reflect.apply(target, thisArg, args);
  }
};

const protectedOp = new Proxy(sensitiveOperation, validator);

class DatabaseConnection {
  constructor(connectionString) {
    this.connectionString = connectionString;
    console.log('Connection created');
  }
}

const SingletonDB = new Proxy(DatabaseConnection, {
  instance: null,
  construct(target, args) {
    if (!this.instance) {
      this.instance = new target(...args);
    }
    return this.instance;
  }
});

